using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    /// <summary>Fetches a post by ID from an external API.</summary>
    [McpServerTool, Description("Fetches a post by its numeric ID from the JSONPlaceholder API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to retrieve.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"posts/{id}");
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        return json.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    /// <summary>Creates a summarization prompt for the given text.</summary>
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences for the summary.")] int maxSentences = 3)
    {
        return
        [
            new(Role.User,
                $"Please provide a concise summary of the following text in at most {maxSentences} sentences:\n\n{text}")
        ];
    }
}

